import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MathArrays_linearCombination_TriageGen3Test {

    private static final double DELTA = 1e-12;

    @Test
    public void testLinearCombination_StandardCase() throws DimensionMismatchException {
        double[] a = {1.0, 2.0, 3.0};
        double[] b = {4.0, 5.0, 6.0};
        // Expected: 1*4 + 2*5 + 3*6 = 4 + 10 + 18 = 32
        double expected = 32.0;
        double actual = MathArrays.linearCombination(a, b);
        assertEquals(expected, actual, DELTA);
    }

    @Test
    public void testLinearCombination_DimensionMismatch() {
        double[] a = {1.0, 2.0};
        double[] b = {1.0, 2.0, 3.0};
        try {
            MathArrays.linearCombination(a, b);
            org.junit.Assert.fail("Expected DimensionMismatchException");
        } catch (DimensionMismatchException e) {
            // Success
        }
    }

    @Test
    public void testLinearCombination_SingleElement() throws DimensionMismatchException {
        // The implementation has a loop: for (int i = 1; i < lenMinusOne; i++)
        // and logic for prodHigh[0], prodHigh[1]. 
        // Note: If len < 2, the logic for sHighPrev/sLowSum might behave specifically.
        // However, the provided code assumes len >= 2 for the sHighPrev/sLowSum logic to be safe.
        // Let's test len = 2 to cover the first block of sHighPrev logic.
        double[] a = {2.0, 3.0};
        double[] b = {4.0, 5.0};
        // Expected: 2*4 + 3*5 = 8 + 15 = 23
        double expected = 23.0;
        double actual = MathArrays.linearCombination(a, b);
        assertEquals(expected, actual, DELTA);
    }

    @Test
    public void testLinearCombination_ThreeElements() throws DimensionMismatchException {
        // Tests the loop: for (int i = 1; i < lenMinusOne; i++)
        double[] a = {1.0, 2.0, 3.0};
        double[] b = {1.0, 1.0, 1.0};
        // Expected: 1*1 + 2*1 + 3*1 = 6
        double expected = 6.0;
        double actual = MathArrays.linearCombination(a, b);
        assertEquals(expected, actual, DELTA);
    }

    @Test
    public void testLinearCombination_NaNHandling() throws DimensionMismatchException {
        // This triggers the Double.isNaN(result) block
        // Using very large numbers to potentially cause overflow/NaN via the splitting logic
        // Or simply providing NaN directly.
        double[] a = {Double.NaN, 1.0};
        double[] b = {1.0, 1.0};

        // result will be NaN, then the code falls back to naive: NaN*1 + 1*1 = NaN
        // To specifically test the fallback 'result = 0' loop, we need the splitting logic to produce NaN
        // but the naive sum to potentially be different, or just ensure we hit the branch.
        // If a contains NaN, the naive loop also produces NaN.

        // Let's use Infinity to force NaN in the splitting math (e.g., inf - inf)
        double[] aInf = {Double.POSITIVE_INFINITY, 1.0};
        double[] bInf = {Double.POSITIVE_INFINITY, 1.0};

        // The complex math (ca - (ca - ai)) with Infinity often results in NaN.
        // The fallback loop: result = inf*inf + 1*1 = inf.
        double actual = MathArrays.linearCombination(aInf, bInf);
        assertEquals(Double.POSITIVE_INFINITY, actual, 0.0);
    }

    @Test
    public void testLinearCombination_ZeroValues() throws DimensionMismatchException {
        double[] a = {0.0, 0.0, 0.0};
        double[] b = {0.0, 0.0, 0.0};
        double expected = 0.0;
        double actual = MathArrays.linearCombination(a, b);
        assertEquals(expected, actual, DELTA);
    }

    @Test
    public void testLinearCombination_NegativeValues() throws DimensionMismatchException {
        double[] a = {-1.0, 2.0};
        double[] b = {3.0, -4.0};
        // -3 + -8 = -11
        double expected = -11.0;
        double actual = MathArrays.linearCombination(a, b);
        assertEquals(expected, actual, DELTA);
    }
}
